<?php
require_once __DIR__.'/../config/app.php';require_admin();$errors=[];
if(is_post()){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);try{if($action==='save'){$name=trim($_POST['name']??'');if($name==='')throw new RuntimeException('Nama kategori wajib diisi.');if($id){db()->prepare('UPDATE categories SET name=?,slug=? WHERE id=?')->execute([$name,unique_slug('categories',$name,$id),$id]);flash('success','Kategori diperbarui.');}else{db()->prepare('INSERT INTO categories(name,slug) VALUES(?,?)')->execute([$name,unique_slug('categories',$name)]);flash('success','Kategori ditambahkan.');}}elseif($action==='delete'){db()->prepare('DELETE FROM categories WHERE id=?')->execute([$id]);flash('success','Kategori dihapus.');}}catch(Throwable $e){flash('danger',$action==='delete'?'Kategori masih digunakan produk dan tidak dapat dihapus.':$e->getMessage());}redirect('admin/categories.php');}
$categories=db()->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();$edit=null;if(isset($_GET['edit'])){foreach($categories as $cat){if((int)$cat['id']===(int)$_GET['edit'])$edit=$cat;}}$pageTitle='Kategori';require APP_ROOT.'/includes/admin-header.php';
?>
<div class="row g-4"><div class="col-lg-4"><div class="admin-card"><div class="admin-card-header"><strong><?= $edit?'Edit':'Tambah' ?> Kategori</strong></div><div class="admin-card-body"><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label class="form-label">Nama kategori</label><input class="form-control mb-3" name="name" value="<?= e($edit['name']??'') ?>" required><button class="btn btn-primary"><?= $edit?'Simpan Perubahan':'Tambah Kategori' ?></button><?php if($edit):?><a class="btn btn-light" href="<?= url('admin/categories.php') ?>">Batal</a><?php endif;?></form></div></div></div><div class="col-lg-8"><div class="admin-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Kategori</th><th>Slug</th><th>Produk</th><th class="text-end">Aksi</th></tr></thead><tbody><?php foreach($categories as $category):?><tr><td><strong><?= e($category['name']) ?></strong></td><td><code><?= e($category['slug']) ?></code></td><td><?= $category['product_count'] ?></td><td class="text-end"><a class="btn btn-sm btn-light" href="?edit=<?= $category['id'] ?>"><i class="bi bi-pencil"></i></a><form method="post" class="d-inline"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $category['id'] ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Hapus kategori ini?"><i class="bi bi-trash"></i></button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php require APP_ROOT.'/includes/admin-footer.php';?>
